    def fish_net_summary(self, rows=None):
        generic = self.profession_storage_summary(
            "net", rows
        )
        return {
            "fish": generic["count"],
            "species": generic["types"],
            "silver": generic["silver"],
            "gold": generic["gold"],
            "mithril": generic["mithril"],
        }

