    async def bulk_sell_container(self, container):
        definition = self.profession_storage_definition(container)
        if not definition:
            await self.send("Nieznany magazyn profesji.")
            return False

        rows_db = self.server.db.storage_rows(
            self.account_id, container
        )
        if not rows_db:
            await self.send(
                f"{self.container_label(container)} jest pusty."
            )
            return False

        sell_rows = []
        for row in rows_db:
            item_id = row["item_id"]
            qty = int(row["quantity"])
            item = ITEMS.get(item_id, {})
            if (
                item_id in definition["ids"]
                and qty > 0
                and self.resource_sale_allowed_here(item_id)
                and (
                    item.get("sell_silver", 0)
                    or item.get("sell_gold", 0)
                    or item.get("sell_mithril", 0)
                )
            ):
                sell_rows.append((item_id, qty))

        if not sell_rows:
            await self.send(
                f"Nie możesz sprzedać zawartości "
                f"{self.container_label(container)} tutaj. "
                f"Sprzedaż: "
                f"{self.resource_sale_location_text(container)}."
            )
            return False

        rewards = self.bulk_sell_rewards_for_rows(sell_rows)

        for item_id, qty in sell_rows:
            if not self.server.db.remove_storage_item(
                self.account_id, container, item_id, qty
            ):
                raise RuntimeError(
                    f"Nie udało się sprzedać {item_id} x{qty}."
                )

        self.character.silver += rewards["silver"]
        self.character.gold += rewards["gold"]
        self.character.mithril += rewards["mithril"]

        await self.gain_charisma_from_bulk_sale(rewards)
        await self.announce_profession_sale_xp(container, rewards["units"])
        self.server.db.save_character(self.character)

        await self.send(
            f"Sprzedajesz {self.resource_sale_buyer_text(container)} cały magazyn: "
            f"{self.container_label(container)}. "
            f"Sztuk: {rewards['units']}. "
            f"Rodzajów: {rewards['types']}."
        )
        await self.send(
            f"Zarobek: {self.sale_reward_text(rewards)}."
        )
        return True

    async def bulk_sell_inventory_items(self):
        rows = self.server.db.inventory(self.account_id)
        equipped_counts = {}
        for equipped in self.server.db.equipment(self.account_id):
            item_id = equipped["item_id"]
            equipped_counts[item_id] = equipped_counts.get(item_id, 0) + 1

        sell_rows = []
        skipped = 0

        for row in rows:
            item_id = row["item_id"]
            qty = int(row["quantity"])
            item = ITEMS.get(item_id, {})
            equipped_count = min(qty, int(equipped_counts.get(item_id, 0)))
            sellable_qty = max(0, qty - equipped_count)

            if sellable_qty <= 0:
                skipped += qty
                continue

            if equipped_count:
                skipped += equipped_count

            # v0.30.20: sell all jest celowo BEZPIECZNE. Hurtowo sprzedaje
            # wyłącznie niezałożone EQ. Mikstury, consumables, loot, materiały,
            # quest itemy, narzędzia i wszystkie inne typy pozostają nietknięte.
            if item.get("type") != "armor":
                skipped += qty
                continue
            if is_character_bound_item(item_id):
                skipped += qty
                continue
            if not self.generic_item_sale_allowed_here():
                skipped += qty
                continue
            if not self.generic_item_is_sellable(item_id, item):
                skipped += qty
                continue
            sell_rows.append((item_id, sellable_qty))

        if not sell_rows:
            await self.send(
                "Nie masz tutaj niezałożonego EQ do sprzedaży. "
                "Sell all nigdy nie sprzedaje mikstur, materiałów, lootu, narzędzi ani quest itemów."
            )
            return False

        rewards = self.bulk_sell_rewards_for_rows(sell_rows)

        for item_id, qty in sell_rows:
            if not self.server.db.remove_item(
                self.account_id, item_id, qty
            ):
                raise RuntimeError(
                    f"Nie udało się sprzedać {item_id} x{qty}."
                )

        self.character.silver += rewards["silver"]
        self.character.gold += rewards["gold"]
        self.character.mithril += rewards["mithril"]

        await self.gain_charisma_from_bulk_sale(rewards)
        await self.announce_profession_sale_xp_for_rows(sell_rows)
        self.server.db.save_character(self.character)

        await self.send(
            f"Sprzedajesz sprzedawcy {self.generic_item_sale_buyer_name()} "
            f"niezałożone EQ z inventory. "
            f"Sztuk: {rewards['units']}. "
            f"Rodzajów: {rewards['types']}."
        )
        await self.send(
            f"Zarobek: {self.sale_reward_text(rewards)}."
        )
        if skipped:
            await self.send(
                f"Pominięto {skipped} sztuk: sell all chroni wszystko poza niezałożonym EQ "
                f"oraz nigdy nie sprzedaje aktualnie założonych części."
            )
        return True

    def logical_sell_equipment_slot(self, slot):
        slot = str(slot or "").strip().lower()
        if slot in ("ring1", "ring2"):
            return "ring"
        if slot in ("charm1", "charm2"):
            return "charm"
        return slot

    def sell_slot_from_query(self, query):
        q = normalize_lookup_text(query)
        if not q:
            return None
        for alias, slot in EQUIPMENT_SLOT_ALIASES.items():
            if normalize_lookup_text(alias) == q:
                return self.logical_sell_equipment_slot(slot)
        return None

    def owned_single_sale_candidates(self, query):
        """v0.23: rozwiązuje sprzedaż WYŁĄCZNIE wśród faktycznie posiadanych,
        wolnych i sprzedawalnych przedmiotów. Dzięki temu `sprzedaj helm` nie
        przeszukuje 26 tysięcy globalnych definicji EQ i nie wybiera losowo.
        """
        q = normalize_lookup_text(query)
        if not q:
            return []
        requested_slot = self.sell_slot_from_query(query)
        rows = []
        for row in self.server.db.inventory(self.account_id):
            item_id = row["item_id"]
            item = ITEMS.get(item_id)
            if not item or not self.generic_item_is_sellable(item_id, item):
                continue
            free_qty = max(
                0, int(row["quantity"]) - self.equipped_quantity_of_item(item_id)
            )
            if free_qty <= 0:
                continue
            if requested_slot:
                if item.get("type") != "armor":
                    continue
                if self.logical_sell_equipment_slot(item.get("slot")) != requested_slot:
                    continue
                rows.append((item_id, item, free_qty))
                continue
            item_name = normalize_lookup_text(item.get("name", ""))
            item_key = normalize_lookup_text(item_id)
            if q == item_name or q == item_key or q in item_name or q in item_key:
                rows.append((item_id, item, free_qty))
        return rows

    async def ask_single_sale_choice(self, query, candidates):
        self.sell_choice_state = {
            "room_id": self.character.room_id,
            "query": str(query or "").strip(),
            "item_ids": [item_id for item_id, _item, _qty in candidates],
        }
        await self.send(
            f"Pasuje kilka twoich wolnych przedmiotów: {len(candidates)}. "
            "Wybierz numer komendą sprzedaj <numer>."
        )
        for number, (item_id, item, free_qty) in enumerate(candidates, 1):
            values = self.generic_item_sale_value(item_id, item)
            await self.send(
                f"{number}. {item['name']}. Wolne sztuki: {free_qty}. "
                f"Cena jednej: {currency_reading_text(values['silver'], values['gold'], values['mithril'])}."
            )

    async def sell_command(self, query):
        raw_query = str(query or "").strip()
        # Numer po liście niejednoznacznych przedmiotów oznacza wybór z tej
        # listy, a nie nazwę globalnego itemu. Lista działa tylko w tym samym sklepie.
        if raw_query.isdigit() and self.sell_choice_state:
            state = self.sell_choice_state
            if state.get("room_id") != self.character.room_id:
                self.sell_choice_state = None
                await self.send("Poprzednia lista sprzedaży wygasła. Wskaż przedmiot ponownie.")
                return
            index = int(raw_query) - 1
            item_ids = list(state.get("item_ids") or ())
            if index < 0 or index >= len(item_ids):
                await self.send(
                    f"Nie ma pozycji {raw_query}. Wybierz numer od 1 do {len(item_ids)}."
                )
                return
            item_id = item_ids[index]
            self.sell_choice_state = None
            await self.sell_resource(item_id)
            return

        if not raw_query.isdigit():
            self.sell_choice_state = None

        target = self.normalize_bulk_sell_target(query)

        if target == "inventory":
            await self.bulk_sell_inventory_items()
            return

        if target in {"net", "bag", "woodpile", "herbbag"}:
            await self.bulk_sell_container(target)
            return

        await self.sell_resource(query)

    def parse_numbered_inventory_query(self, query):
        raw = str(query or "").strip()
        match = re.match(r"^\s*(\d+)\s*[\.\)]\s*(.+?)\s*$", raw)
        if not match:
            return None, raw
        return max(1, int(match.group(1))), match.group(2).strip()

    async def sell_resource(self, query):
        copy_number, item_query = self.parse_numbered_inventory_query(query)

        # v0.23: dla zwykłej sprzedaży najpierw patrzymy na RZECZY GRACZA,
        # nie na cały katalog ITEMS. Obsługuje to m.in. `sprzedaj helm` i
        # fragment nazwy. Przy wielu trafieniach zawsze jest jawny wybór.
        found = None
        if copy_number is None:
            owned_candidates = self.owned_single_sale_candidates(item_query)
            if len(owned_candidates) == 1:
                item_id, item, _free_qty = owned_candidates[0]
                found = (item_id, item)
            elif len(owned_candidates) > 1:
                await self.ask_single_sale_choice(item_query, owned_candidates)
                return

        if not found:
            found = find_by_name(ITEMS, item_query)
        if not found:
            await self.send(
                "Nie rozpoznaję takiego przedmiotu albo pasuje kilka pozycji. "
                "Dla EQ możesz użyć typu, np. sprzedaj helm."
            )
            return
        item_id, item = found

        if self.market_buyer_rejects_item(item_id, item):
            await self.send(
                "Handlarz Skupu Radan nie skupuje materiałów rzemieślniczych ani zasobów profesyjnych. "
                "Ryby, rudy i minerały, drewno oraz zioła sprzedawaj u właściwych fachowców."
            )
            return

        # v0.8.51: zwykłe przedmioty (np. talizmany, pierścienie, pancerze)
        # można sprzedać w dowolnym normalnym sklepie.
        if item.get("type") != "resource" and item_id not in MINING_STORAGE_IDS:
            if not self.generic_item_is_sellable(item_id, item):
                await self.send("Tego przedmiotu nie można sprzedać.")
                return
            if not self.generic_item_sale_allowed_here():
                await self.send(
                    "Zwykłe przedmioty sprzedasz w lokacji z normalnym sklepem. "
                    "Przejdź do sklepu i użyj: sprzedaj <nazwa przedmiotu>."
                )
                return
            owned_qty = self.server.db.item_qty(self.account_id, item_id)
            if owned_qty <= 0:
                await self.send("Nie masz tego przedmiotu.")
                return
            equipped_count = sum(
                1 for row in self.server.db.equipment(self.account_id)
                if row["item_id"] == item_id
            )
            if copy_number is not None:
                if copy_number > owned_qty:
                    await self.send(
                        f"Masz tylko {owned_qty} sztuk: {item['name']}."
                    )
                    return
                if copy_number <= equipped_count:
                    await self.send(
                        f"Egzemplarz {copy_number}: {item['name']} jest założony. "
                        f"Sprzedaj egzemplarz od {equipped_count + 1} wzwyż albo zdejmij talizman/EQ."
                    )
                    return
            elif owned_qty <= equipped_count:
                await self.send(
                    f"Wszystkie posiadane sztuki {item['name']} są założone. "
                    "Najpierw zdejmij jedną albo wskaż wolny egzemplarz numerem."
                )
                return
            values = self.generic_item_sale_value(item_id, item)
            if not self.server.db.remove_item(self.account_id, item_id, 1):
                await self.send("Nie udało się sprzedać przedmiotu.")
                return
            self.character.silver += values["silver"]
            self.character.gold += values["gold"]
            self.character.mithril += values["mithril"]
            await self.gain_charisma_from_sale(legacy_currency_to_coins(values["silver"], values["gold"], values["mithril"]))
            self.server.db.save_character(self.character)
            copy_text = f" egzemplarz {copy_number}" if copy_number is not None else ""
            await self.send(
                f"Sprzedajesz sprzedawcy {self.generic_item_sale_buyer_name()}{copy_text}: "
                f"{item['name']} za "
                f"{currency_reading_text(values['silver'], values['gold'], values['mithril'])}."
            )
            return

        fish_items = FISH_STORAGE_IDS
        ore_items = MINING_STORAGE_IDS
        wood_items = WOOD_STORAGE_IDS
        herb_items = HERB_STORAGE_IDS

        if item_id in fish_items:
            source_container = "net"
        elif item_id in ore_items:
            source_container = "bag"
        elif item_id in wood_items:
            source_container = "woodpile"
        elif item_id in herb_items:
            source_container = "herbbag"
        else:
            source_container = None

        storage_quantity = (
            self.server.db.storage_qty(self.account_id, source_container, item_id)
            if source_container else 0
        )
        inventory_quantity = self.server.db.item_qty(self.account_id, item_id)
        if storage_quantity <= 0 and inventory_quantity <= 0:
            await self.send("Nie masz tego przedmiotu.")
            return

        if item_id in fish_items and self.character.room_id != "fish_market":
            await self.send("Ryby skupują tylko rybacy na Targu Rybnym.")
            return
        if item_id in ore_items and self.character.room_id != "mountain_market":
            await self.send("Rudy, minerały i surowe klejnoty skupuje tylko Handlarka Minerałów Dagna na Górskim Targu Minerałów.")
            return
        if item_id in wood_items and self.character.room_id != "lumberjack_camp":
            await self.send("Drewno skupuje tylko Drwal Bran w Obozie Drwala.")
            return
        if item_id in herb_items and self.character.room_id != "herbalist_hut":
            await self.send("Zioła skupuje tylko Zielarka Liora w Chacie Zielarki.")
            return

        removed = False
        if source_container and self.server.db.storage_qty(
            self.account_id, source_container, item_id
        ) > 0:
            removed = self.server.db.remove_storage_item(
                self.account_id, source_container, item_id, 1
            )
        elif self.server.db.item_qty(self.account_id, item_id) > 0:
            removed = self.server.db.remove_item(
                self.account_id, item_id, 1
            )

        if not removed:
            await self.send("Nie masz tego surowca.")
            return

        # v0.19: sprzedaż zasobów skaluje się razem z globalną ekonomią.
        reward_coins = v0190_resource_sale_coins(item_id, item)
        self.character.silver += reward_coins
        await self.gain_charisma_from_sale(reward_coins)
        await self.announce_profession_sale_xp(source_container, 1)
        self.server.db.save_character(self.character)

        buyer = self.resource_sale_buyer_text(source_container)
        await self.send(
            f"Sprzedajesz {buyer}: {item['name']} za "
            + currency_reading_text(reward_coins, 0, 0) + "."
        )

    def recipe_container_for_item(self, item_id):
        if item_id in FISH_STORAGE_IDS:
            return "net"
        if item_id in MINING_STORAGE_IDS:
            return "bag"
        if item_id in WOOD_STORAGE_IDS:
            return "woodpile"
        if item_id in HERB_STORAGE_IDS:
            return "herbbag"
        if item_id in CRAFT_MATERIAL_STORAGE_IDS:
            return "craftbox"
        return None

    def available_recipe_item(self, item_id):
        container = self.recipe_container_for_item(item_id)
        storage = (
            self.server.db.storage_qty(self.account_id, container, item_id)
            if container else 0
        )
        return storage + self.server.db.item_qty(self.account_id, item_id)

    def consume_recipe_item(self, item_id, quantity):
        remaining = max(0, int(quantity))
        container = self.recipe_container_for_item(item_id)

        if container and remaining > 0:
            stored = self.server.db.storage_qty(
                self.account_id, container, item_id
            )
            take = min(stored, remaining)
            if take > 0:
                if not self.server.db.remove_storage_item(
                    self.account_id, container, item_id, take
                ):
                    return False
                remaining -= take

        if remaining > 0:
            if not self.server.db.remove_item(
                self.account_id, item_id, remaining
            ):
                return False
            remaining = 0

        return True

    def recipe_station_text(self, stations):
        return " lub ".join(ROOMS[room_id]["name"] for room_id in stations)

    def recipe_distinct_ingredient_choices(self, recipe):
        pool = tuple(recipe.get("distinct_ingredient_pool") or ())
        needed = max(0, int(recipe.get("distinct_ingredient_count", 0) or 0))
        available = [
            item_id for item_id in pool
            if self.available_recipe_item(item_id) > 0
        ]
        return available[:needed]

    def recipe_pooled_ingredient_choices(self, recipe):
        """Wybiera dowolną liczbę sztuk z jednej puli, także kilka tego samego ID."""
        pool = tuple(recipe.get("pooled_ingredient_pool") or ())
        needed = max(0, int(recipe.get("pooled_ingredient_count", 0) or 0))
        selected = []
        remaining = needed
        for item_id in pool:
            if remaining <= 0:
                break
            available = max(0, int(self.available_recipe_item(item_id)))
            take = min(remaining, available)
            if take > 0:
                selected.extend([item_id] * take)
                remaining -= take
        return selected

    def recipe_ingredients_text(self, recipe):
        parts = [
            f"{ITEMS[item_id]['name']} x{quantity}"
            for item_id, quantity in recipe["ingredients"].items()
        ]
        distinct_pool = tuple(recipe.get("distinct_ingredient_pool") or ())
        distinct_count = max(0, int(recipe.get("distinct_ingredient_count", 0) or 0))
        if distinct_pool and distinct_count:
            label = recipe.get("distinct_ingredient_label", "różne składniki")
            examples = ", ".join(ITEMS[item_id]["name"] for item_id in distinct_pool)
            parts.append(f"{distinct_count} {label} ({examples})")
        pooled_pool = tuple(recipe.get("pooled_ingredient_pool") or ())
        pooled_count = max(0, int(recipe.get("pooled_ingredient_count", 0) or 0))
        if pooled_pool and pooled_count:
            label = recipe.get("pooled_ingredient_label", "dowolne składniki z puli")
            parts.append(f"{pooled_count} {label}")
        return ", ".join(parts)

    async def show_recipes(self, mode=""):
        mode = self.normalize_description_query(mode)
        craft_modes = {
            "craft", "stworz", "rzemioslo", "kowalstwo",
            "smithing", "blacksmithing", "kuj",
        }
        cook_modes = {
            "cook", "gotuj", "gotowanie",
        }
        alchemy_modes = {
            "alchemy", "alchemia",
        }
        jewel_modes = {
            "jubilerstwo", "jewelcrafting", "jewelry",
            "bizuteria", "biżuteria", "jub",
        }

        if not mode:
            show_craft = show_cook = show_alchemy = show_jewel = True
        elif mode in craft_modes:
            show_craft = True
            show_cook = False
            show_alchemy = False
            show_jewel = False
        elif mode in cook_modes:
            show_craft = False
            show_cook = True
            show_alchemy = False
            show_jewel = False
        elif mode in alchemy_modes:
            show_craft = False
            show_cook = False
            show_alchemy = True
            show_jewel = False
        elif mode in jewel_modes:
            show_craft = False
            show_cook = False
            show_alchemy = False
            show_jewel = True
        else:
            show_craft = show_cook = show_alchemy = show_jewel = True

        if show_craft:
            await self.send("RECEPTURY RZEMIOSŁA I KOWALSTWA")
            for recipe in CRAFT_RECIPES.values():
                await self.send(
                    f"{recipe['name']}. Składniki: "
                    f"{self.recipe_ingredients_text(recipe)}. "
                    f"Miejsce: {self.recipe_station_text(recipe['stations'])}. "
                    f"{self.recipe_level_requirement_text(CRAFT_RECIPES, recipe)} "
                    f"{recipe['desc']}"
                )

        if show_cook:
            await self.send("RECEPTURY GOTOWANIA")
            for recipe in COOK_RECIPES.values():
                await self.send(
                    f"{recipe['name']}. Składniki: "
                    f"{self.recipe_ingredients_text(recipe)}. "
                    f"Miejsce: {self.recipe_station_text(recipe['stations'])}. "
                    f"{self.recipe_level_requirement_text(COOK_RECIPES, recipe)} "
                    f"{recipe['desc']}"
                )

        if show_alchemy:
            await self.send("RECEPTURY ALCHEMII")
            for recipe in ALCHEMY_RECIPES.values():
                await self.send(
                    f"{recipe['name']}. Składniki: "
                    f"{self.recipe_ingredients_text(recipe)}. "
                    f"Miejsce: {self.recipe_station_text(recipe['stations'])}. "
                    f"{self.recipe_level_requirement_text(ALCHEMY_RECIPES, recipe)} "
                    f"{recipe['desc']}"
                )

        if show_jewel:
            await self.send("RECEPTURY JUBILERSTWA")
            for recipe in JEWELCRAFT_RECIPES.values():
                await self.send(
                    f"{recipe['name']}. Składniki: "
                    f"{self.recipe_ingredients_text(recipe)}. "
                    f"Miejsce: {self.recipe_station_text(recipe['stations'])}. "
                    f"{self.recipe_level_requirement_text(JEWELCRAFT_RECIPES, recipe)} "
                    f"{recipe['desc']}"
                )

    def recipe_profession_name(self, recipes, recipe=None):
        if recipe and recipe.get("profession"):
            return str(recipe["profession"])
        if recipes is CRAFT_RECIPES:
            return "Kowalstwo"
        if recipes is ALCHEMY_RECIPES:
            return "Alchemia"
        if recipes is JEWELCRAFT_RECIPES:
            return "Jubilerstwo"
        return "Gotowanie"

    def recipe_tool_info(self, recipes, recipe=None):
        if recipe and recipe.get("tool_type"):
            mapping = {
                "fishing": ("fishing_rod", "Wędka"),
                "mining": ("pickaxe", "Kilof"),
                "woodcutting": ("saw", "Piła"),
                "crafting": ("crafting_hammer", "Młot Rzemieślniczy"),
                "cooking": ("chef_knife", "Nóż Kucharski"),
                "herbalism": ("herbalist_sickle", "Sierp Zielarski"),
                "alchemy": ("alchemy_mortar", "Moździerz Alchemiczny"),
                "jewelcrafting": ("jeweler_pliers", "Szczypce Jubilerskie"),
            }
            tool_type = str(recipe["tool_type"])
            item_id, name = mapping[tool_type]
            return tool_type, recipe.get("tool_item_id", item_id), recipe.get("tool_name", name)
        if recipes is CRAFT_RECIPES:
            return "crafting", "crafting_hammer", "Młot Rzemieślniczy"
        if recipes is ALCHEMY_RECIPES:
            return "alchemy", "alchemy_mortar", "Moździerz Alchemiczny"
        if recipes is JEWELCRAFT_RECIPES:
            return "jewelcrafting", "jeweler_pliers", "Szczypce Jubilerskie"
        return "cooking", "chef_knife", "Nóż Kucharski"

    def recipe_level_requirement_text(self, recipes, recipe):
        profession = self.recipe_profession_name(recipes, recipe)
        required = max(1, int(
            recipe.get("min_profession_level", recipe.get("min_tool_level", 1)) or 1
        ))
        _tool_type, _tool_item, tool_name = self.recipe_tool_info(recipes, recipe)
        required_tier = required_tool_tier_for_level(required)
        return (
            f"Wymaga: {profession} level {required} oraz "
            f"{tool_name} Tier {required_tier}+."
        )

    async def perform_recipe(self, query, recipes, action_name):
        if self.combat_mob_key:
            await self.send(
                f"Nie możesz wykonywać akcji {action_name} podczas walki."
            )
            return False

        found = find_by_name(recipes, query)
        if not found:
            await self.send("Nie rozpoznaję tej receptury. Wpisz receptury.")
            return False
        recipe_id, recipe = found

        tool_type, tool_item_id, tool_name = self.recipe_tool_info(recipes, recipe)
        if self.server.db.item_qty(self.account_id, tool_item_id) <= 0:
            shop_room = TOOL_SHOP_ROOMS.get(tool_item_id)
            room_name = ROOMS.get(shop_room, {}).get("name", "właściwym sklepie profesji")
            seller_id = SHOP_SELLERS.get(shop_room)
            seller_name = NPCS.get(seller_id, {}).get("name", "specjalisty profesji")
            await self.send(
                f"Do tej receptury potrzebujesz: {tool_name}. "
                f"Kupisz narzędzie u {seller_name}, lokacja: {room_name}."
            )
            return False

        tool_row = self.server.db.tool(self.account_id, tool_type)
        old_tool_level = int(tool_row["level"])

        profession = self.recipe_profession_name(recipes, recipe)
        profession_row = self.server.db.profession(self.account_id, profession)
        profession_level = int(profession_row["level"])
        required_profession = max(
            1,
            int(recipe.get("min_profession_level", recipe.get("min_tool_level", 1)) or 1),
        )
        if profession_level < required_profession:
            await self.send(
                f"{recipe['name']} wymaga {profession} level "
                f"{required_profession}, a masz {profession_level}."
            )
            return False

        required_tool_tier = required_tool_tier_for_level(required_profession)
        current_tool_tier = tool_tier(old_tool_level)
        if current_tool_tier < required_tool_tier:
            await self.send(
                f"{recipe['name']} wymaga {tool_name} Tier "
                f"{required_tool_tier}+, a masz Tier {current_tool_tier}."
            )
            return False

        if self.character.room_id not in recipe["stations"]:
            await self.send(
                f"Tę recepturę wykonasz w: "
                f"{self.recipe_station_text(recipe['stations'])}."
            )
            return False

        missing = []
        for item_id, quantity in recipe["ingredients"].items():
            have = self.available_recipe_item(item_id)
            if have < quantity:
                missing.append(
                    f"{ITEMS[item_id]['name']}: masz {have}, potrzeba {quantity}"
                )

        distinct_pool = tuple(recipe.get("distinct_ingredient_pool") or ())
        distinct_needed = max(0, int(recipe.get("distinct_ingredient_count", 0) or 0))
        distinct_choices = self.recipe_distinct_ingredient_choices(recipe)
        if distinct_pool and len(distinct_choices) < distinct_needed:
            names = ", ".join(ITEMS[item_id]["name"] for item_id in distinct_pool)
            missing.append(
                f"różne gatunki: masz {len(distinct_choices)}, potrzeba {distinct_needed}; "
                f"liczą się {names}"
            )

        pooled_pool = tuple(recipe.get("pooled_ingredient_pool") or ())
        pooled_needed = max(0, int(recipe.get("pooled_ingredient_count", 0) or 0))
        pooled_choices = self.recipe_pooled_ingredient_choices(recipe)
        if pooled_pool and len(pooled_choices) < pooled_needed:
            label = recipe.get("pooled_ingredient_label", "składniki z puli")
            missing.append(
                f"{label}: masz {len(pooled_choices)}, potrzeba {pooled_needed}"
            )

        if missing:
            await self.send("Brakuje składników:")
            for line in missing:
                await self.send(line + ".")
            return False

        action_seconds = self.recipe_action_seconds(
            tool_type, profession_level, recipe
        )
        await self.send(
            f"Rozpoczynasz {action_name}. "
            f"{self.tool_action_label(tool_type)}: "
            f"{action_seconds} sekund."
        )
        await asyncio.sleep(action_seconds)

        for item_id, quantity in recipe["ingredients"].items():
            if not self.consume_recipe_item(item_id, quantity):
                await self.send(
                    "Nie udało się pobrać składników. Receptura przerwana."
                )
                return False

        if distinct_pool and distinct_needed:
            distinct_choices = self.recipe_distinct_ingredient_choices(recipe)
            if len(distinct_choices) < distinct_needed:
                await self.send(
                    "Nie masz już wymaganych różnych składników. Receptura przerwana."
                )
                return False
            for item_id in distinct_choices[:distinct_needed]:
                if not self.consume_recipe_item(item_id, 1):
                    await self.send(
                        "Nie udało się pobrać różnych składników. Receptura przerwana."
                    )
                    return False

        if pooled_pool and pooled_needed:
            pooled_choices = self.recipe_pooled_ingredient_choices(recipe)
            if len(pooled_choices) < pooled_needed:
                await self.send(
                    "Nie masz już wymaganej liczby składników z puli. Receptura przerwana."
                )
                return False
            for item_id in pooled_choices[:pooled_needed]:
                if not self.consume_recipe_item(item_id, 1):
                    await self.send(
                        "Nie udało się pobrać składników z puli. Receptura przerwana."
                    )
                    return False

        output_id = recipe["output"]
        quantity = int(recipe.get("quantity", 1))

        tier = tool_tier(old_tool_level)
        bonus_chance = tool_tier_bonus_chance(old_tool_level)

        bonus_quantity = 0
        if bonus_chance > 0 and random.random() < bonus_chance:
            bonus_quantity = quantity

        total_quantity = quantity + bonus_quantity
        self.server.db.add_item(
            self.account_id, output_id, total_quantity
        )
        await self.record_item_collection(
            output_id, source="Rzemiosło", announce=True,
            record_history=False, amount=total_quantity
        )
        self.server.db.add_lifetime_stat(self.account_id, "craft_actions", 1)
        self.server.db.add_lifetime_stat(self.account_id, "crafted_items", total_quantity)
        self.server.db.add_lifetime_stat(self.account_id, "profession_actions", 1)

        destination = (
            "Szkatułki Rzemieślniczej"
            if output_id in CRAFT_MATERIAL_STORAGE_IDS
            else "zwykłego ekwipunku"
        )
        await self.send(
            f"{action_name.capitalize()}: {ITEMS[output_id]['name']} "
            f"x{quantity}. Przedmiot trafia do {destination}."
        )

        if bonus_quantity > 0:
            if tool_type == "cooking":
                await self.send(
                    f"Bonus Tieru {tier} Noża Kucharskiego: "
                    f"przygotowujesz dodatkowo "
                    f"{ITEMS[output_id]['name']} "
                    f"x{bonus_quantity}."
                )
            elif tool_type == "alchemy":
                await self.send(
                    f"Bonus Tieru {tier} Moździerza Alchemicznego: "
                    f"warzysz dodatkowo "
                    f"{ITEMS[output_id]['name']} "
                    f"x{bonus_quantity}."
                )
            elif tool_type == "jewelcrafting":
                await self.send(
                    f"Bonus Tieru {tier} Szczypiec Jubilerskich: "
                    f"wykonujesz dodatkowo "
                    f"{ITEMS[output_id]['name']} "
                    f"x{bonus_quantity}."
                )
            elif tool_type == "woodcutting":
                await self.send(
                    f"Bonus Tieru {tier} Piły: "
                    f"obrabiasz dodatkowo "
                    f"{ITEMS[output_id]['name']} "
                    f"x{bonus_quantity}."
                )
            else:
                await self.send(
                    f"Bonus Tieru {tier} {tool_name}: "
                    f"wytwarzasz dodatkowo "
                    f"{ITEMS[output_id]['name']} "
                    f"x{bonus_quantity}."
                )

        if tool_type in (
            "alchemy", "cooking", "crafting",
            "jewelcrafting", "woodcutting",
        ):
            await self.announce_craft_quest_progress(
                output_id,
                total_quantity,
            )

        tool_xp = (
            roll_crafting_xp(recipe["tool_xp"])
            if "tool_xp" in recipe
            else 8 + random.randint(0, 4)
        )
        profession_xp = (
            roll_crafting_xp(recipe["profession_xp"])
            if "profession_xp" in recipe
            else 10 + random.randint(0, 5)
        )
        messages, _profession_level_after, new_tool_level = self.grant_profession_progress(
            profession, profession_xp, tool_type, tool_xp
        )
        for message in messages:
            await self.send(message)

        await self.sync_extended_achievements()
        if new_tool_level != old_tool_level:
            await self.send(
                f"{tool_name} ma teraz level {new_tool_level}, "
                f"Tier {tool_tier(new_tool_level)}: "
                f"{tool_tier_name(tool_type, new_tool_level)}."
            )

        return True

